'use strict';

// MODULES //

var isNumber = require( '@stdlib/assert/is-number' );
var isCollection = require( '@stdlib/assert/is-collection' );
var isNonNegativeInteger = require( '@stdlib/assert/is-nonnegative-integer' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Evaluates a polynomial using Horner's rule.
*
* @param {number} x - input value
* @param {Collection<number>} coef - polynomial coefficients
* @param {number} N - degree of the polynomial
*
* @throws {TypeError} if the first argument is not a number
* @throws {TypeError} if the second argument is not a collection
* @throws {TypeError} if the third argument is not a non-negative integer
* @throws {RangeError} if the degree is greater than or equal to the number of coefficients
*
* @returns {number} polynomial value
*
* @example
* var coef = [ 1.0, 2.0, 3.0 ];
* var v = polevl( 2.0, coef, 2 );
* // returns 17.0  ( 1 + 2 * ( 2 ) + 3 * ( 2^2 ) )
*/
function polevl( x, coef, N ) {
	var ans;
	var i;

	if ( isNaN( x ) ) {
		return NaN;
	}

	if ( !isNumber( x ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a number. Value: `%s`.', x ) );
	}
	if ( !isCollection( coef ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be an array-like object. Value: `%s`.', coef ) );
	}
	if ( !isNonNegativeInteger( N ) ) {
		throw new TypeError( format( 'invalid argument. Third argument must be a non-negative integer. Value: `%s`.', N ) );
	}
	if ( N >= coef.length ) {
		throw new RangeError( format( 'invalid argument. Third argument must be less than the number of coefficients. Value: `%s`.', N ) );
	}

	ans = coef[ N ];
	for ( i = N-1; i >= 0; i-- ) {
		ans = ( ans * x ) + coef[ i ];
	}
	return ans;
}


// EXPORTS //

module.exports = polevl;
